$actor=wp_insert_user(['user_login'=>'amsec-policy-admin-'.bin2hex(random_bytes(4)),'user_pass'=>$password,'role'=>'administrator']);$target=wp_insert_user(['user_login'=>'amsec-policy-target-'.bin2hex(random_bytes(4)),'user_pass'=>$targetPassword,'role'=>'administrator']);$subscriber=wp_insert_user(['user_login'=>'amsec-policy-reader-'.bin2hex(random_bytes(4)),'user_pass'=>$targetPassword,'role'=>'subscriber']);
