}finally{wp_set_current_user(1);$_COOKIE=[];foreach([$actor,$target,$subscriber] as $id){wp_delete_user($id);}if($old===null){delete_option(RequiredTotpPolicy::OPTION);}else{update_option(RequiredTotpPolicy::OPTION,$old,false);}}
